using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.Architecture;

/// <summary>Layer rules, scanned from the compiled metadata of each layer.</summary>
public sealed class LayerDependencyTests
{
    // Allow-list: the language core only. Anything else (System.IO, System.Net.*, System.Data, frameworks...) is a violation.
    private static readonly HashSet<string> LanguageCore =
    [
        "System",
        "System.Collections",
        "System.Collections.Generic",
        "System.Collections.Immutable",
        "System.Linq",
        "System.Threading",
        "System.Threading.Tasks",
        "System.Runtime.CompilerServices",
        "System.Diagnostics.CodeAnalysis",
    ];

    // Types inside allowed namespaces that still reach the outside world.
    private static readonly HashSet<string> TechnicalTypes =
    [
        "System.Console",
        "System.Environment",
        "System.AppContext",
        "System.Activator",
        "System.GC",
        "System.TimeZoneInfo",
    ];

    [Fact]
    public void Domain_depends_only_on_itself_and_the_language_core()
        => AssertOnlyDependsOn(typeof(Money).Assembly, "PaymentAuthorization.Domain");

    [Fact]
    public void Application_depends_only_on_Domain_itself_and_the_language_core()
        => AssertOnlyDependsOn(typeof(AuthorizePayment).Assembly, "PaymentAuthorization.Domain", "PaymentAuthorization.Application");

    [Fact]
    public void Infrastructure_does_not_depend_on_anything_outward()
    {
        // Infrastructure may use technical details, but is the outermost layer here: nothing may reference it.
        var infrastructure = typeof(FileSystemReceiptStore).Assembly.GetName().Name;
        foreach (var inner in new[] { typeof(Money).Assembly, typeof(AuthorizePayment).Assembly })
            Assert.DoesNotContain(inner.GetReferencedAssemblies(), a => a.Name == infrastructure);
    }

    private static void AssertOnlyDependsOn(Assembly assembly, params string[] ownNamespaces)
    {
        var violations = ReferencedTypes(assembly)
            .Where(t => !ownNamespaces.Contains(t.Namespace) && !LanguageCore.Contains(t.Namespace)
                        || TechnicalTypes.Contains($"{t.Namespace}.{t.Name}"))
            .Select(t => $"{t.Namespace}.{t.Name}")
            .Distinct()
            .Order()
            .ToList();

        Assert.True(violations.Count == 0,
            $"Violations in {assembly.GetName().Name}: {string.Join(", ", violations)}");
    }

    private static IEnumerable<(string Namespace, string Name)> ReferencedTypes(Assembly assembly)
    {
        using var stream = File.OpenRead(assembly.Location);
        using var pe = new PEReader(stream);
        var reader = pe.GetMetadataReader();
        return reader.TypeReferences
            .Select(h => reader.GetTypeReference(h))
            .Where(t => t.ResolutionScope.Kind != HandleKind.TypeReference) // nested types follow their parent
            .Select(t => (reader.GetString(t.Namespace), reader.GetString(t.Name)))
            .ToList();
    }
}
EOF
